//int f(int a[],int n,int x){int i;for(i=0;i<n;i++)if(a[i]==x)return i;return -1;}
int binary_search(int a[],int n,int x){
int l=0,h=n-1,m;
while(l<=h){
m=(l+h)/2;
if(a[m]==x)return m;
if(a[m]<x)l=m;else h=m;
}
return -1;
}
